function update(dt) {
    // Move ship
    if (keys['ArrowLeft'] && ship.x > 0) ship.x -= ship.speed;
    if (keys['ArrowRight'] && ship.x + ship.w < width) ship.x += ship.speed;
    if (keys['ArrowUp'] && ship.y > 0) ship.y -= ship.speed;
    if (keys['ArrowDown'] && ship.y + ship.h < height) ship.y += ship.speed;

    // Move asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.x += a.vx;
      a.y += a.vy;
      // Remove off‑screen asteroids
      if (a.x < -a.radius * 2 || a.x > width + a.radius * 2 || a.y < -a.radius * 2 || a.y > height + a.radius * 2) {
        asteroids.splice(i, 1);
      }
    }

    // Collision detection (circle‑rect)
    for (const a of asteroids) {
      const distX = Math.abs(a.x - (ship.x + ship.w / 2));
      const distY = Math.abs(a.y - (ship.y + ship.h / 2));
      if (distX > (ship.w / 2 + a.radius) || distY > (ship.h / 2 + a.radius)) continue;
      if (distX <= ship.w / 2 || distY <= ship.h / 2) { gameOver = true; break; }
      const dx = distX - ship.w / 2;
      const dy = distY - ship.h / 2;
      if (dx * dx + dy * dy <= a.radius * a.radius) { gameOver = true; break; }
    }
  }

